`timescale 1ns/1ps

interface syndram_if #(
  parameter int unsigned NUM_SUBCH = 2,
  parameter int unsigned DQ_WIDTH = 12
) (
  input logic [NUM_SUBCH-1:0] CK_t,
  input logic [NUM_SUBCH-1:0] CK_c,
  input logic RESET_n,
  input logic [NUM_SUBCH-1:0] CS,
  input logic [NUM_SUBCH-1:0][3:0] CA,
  inout wire [NUM_SUBCH-1:0][DQ_WIDTH-1:0] DQ,
  input logic [NUM_SUBCH-1:0] WCK_t,
  input logic [NUM_SUBCH-1:0] WCK_c,
  input logic [NUM_SUBCH-1:0] RDQS_t,
  input logic [NUM_SUBCH-1:0] RDQS_c,
  input logic ALERT,
  input logic [NUM_SUBCH-1:0] check_even,
  input logic [NUM_SUBCH-1:0] pamm_hit,
  input logic [NUM_SUBCH-1:0] mrr_valid,
  input logic [NUM_SUBCH-1:0][7:0] mrr_ma,
  input logic [NUM_SUBCH-1:0][7:0] mrr_op,
  input logic eff_status,
  input logic eff_cntl,
  input logic [3:0] mr0_density,
  input logic [NUM_SUBCH-1:0] rank,
  input logic [NUM_SUBCH-1:0] is_dft,
  input logic [NUM_SUBCH-1:0] is_cbt,
  input reg[NUM_SUBCH-1:0][127:0] tb_cmd_string
);

  import syndram_sample_pkg::*;

  localparam int unsigned SYNDRAM_CA_WIDTH = 4;

  initial begin
    if (!(NUM_SUBCH inside {1, 2})) begin
      $error("syndram_if NUM_SUBCH must be 1 or 2");
    end
    if (DQ_WIDTH != 12) begin
      $error("syndram_if DQ_WIDTH must be 12 for SYNDRAM x12 sub-channels");
    end
  end

  logic [NUM_SUBCH-1:0] command_started_q;
  logic [NUM_SUBCH-1:0] check_even_q;
  logic [NUM_SUBCH-1:0] pamm_pos_q;
  logic [NUM_SUBCH-1:0] pamm_r1_q;
  logic [NUM_SUBCH-1:0] cs_pos_q;
  logic [NUM_SUBCH-1:0] cs_r1_q;
  logic [NUM_SUBCH-1:0] cs_r2_q;
