  endfunction

  function automatic realtime ypu_mr_op_unsigned(
    input int unsigned sc,
    input logic [7:0] mr_addr,
    input int unsigned hi,
    input int unsigned lo
  );
    logic [7:0] value;
    logic [7:0] mask;
    int unsigned width;
    value = ypu_mr_value(sc, ypu_mr_fsp_op(sc), mr_addr);
    width = (hi >= lo) ? (hi - lo + 1) : 0;
    mask = (width >= 8) ? 8'hff : ((8'h01 << width) - 8'h01);
    ypu_mr_op_unsigned = realtime'((value >> lo) & mask);
  endfunction

