  typedef struct {
    bit valid;
    real ck_frequency_mhz;
    real wck_frequency_mhz;
    real data_rate_mbps;
  } syndram_rate_bin_t;

  function automatic syndram_rate_bin_t map_ck_period_to_rate(
      input longint unsigned period_ps
  );
    syndram_rate_bin_t rate_bin;

    rate_bin = '{
      valid: 1'b0,
      ck_frequency_mhz: 0.0,
      wck_frequency_mhz: 0.0,
      data_rate_mbps: 0.0
    };

    case (period_ps) inside
      // Add rate bins using this template. Keep ranges exhaustive and
      // non-overlapping, and choose values inside the ontology intervals.
      // [PERIOD_PS_MIN:PERIOD_PS_MAX]: begin
      //   rate_bin = '{
      //     valid: 1'b1,
      //     ck_frequency_mhz: CK_FREQUENCY_MHZ,
      //     wck_frequency_mhz: WCK_FREQUENCY_MHZ,
      //     data_rate_mbps: DATA_RATE_MBPS
      //   };
      // end

      default: begin
        // Preserve the existing behavior until all explicit bins are filled.
        if (period_ps > 0) begin
          rate_bin = '{
            valid: 1'b1,
            ck_frequency_mhz: $floor(1000000.0 / period_ps),
            wck_frequency_mhz: $floor(2000000.0 / period_ps),
            data_rate_mbps: $floor(4000000.0 / period_ps)
          };
        end
      end
    endcase

    return rate_bin;
  endfunction

