  function automatic syndram_raw_cmd_sample_t make_raw_sample(input int unsigned sc);
    syndram_raw_cmd_sample_t raw;
    raw = '{default: '0};
    raw.valid = 1'b1;
    raw.subch = sc[0];
    raw.cs_r1 = cs_r1_q[sc];
    raw.cs_r2 = cs_r2_q[sc];
    raw.ca_r1 = ca_r1_q[sc];
    raw.ca_f1 = ca_f1_q[sc];
    raw.ca_r2 = ca_r2_q[sc];
    raw.ca_f2 = ca_f2_q[sc];
    raw.r1_even = 1'b1;
    raw.r2_even = 1'b0;
    raw.r1_time = r1_time_q[sc];
    raw.f1_time = f1_time_q[sc];
    raw.r2_time = r2_time_q[sc];
    raw.f2_time = f2_time_q[sc];
    return raw;
  endfunction

  function automatic bit ca_known(input logic [SYNDRAM_CA_WIDTH-1:0] ca);
    return !$isunknown(ca);
  endfunction

  function automatic bit bit_known(input logic value);
    return !$isunknown(value);
  endfunction

  function automatic bit bit_is(input logic value, input bit expected);
    return !$isunknown(value) && value == expected;
  endfunction

  function automatic bit static_efficiency_mode_active();
    return bit_is(eff_status, 1'b1);
  endfunction

  function automatic bit dynamic_efficiency_mode_active();
    return bit_is(eff_status, 1'b0) && bit_is(eff_cntl, 1'b1);
  endfunction

  function automatic bit normal_mode_active();
    return bit_is(eff_status, 1'b0) && bit_is(eff_cntl, 1'b0);
  endfunction

  function automatic bit efficiency_mode_active();
    return static_efficiency_mode_active() || dynamic_efficiency_mode_active();
  endfunction

  function automatic bit tb_cmd_is_pdx(input int unsigned sc);
    return (tb_cmd_string[sc] == "0_pdx" || tb_cmd_string[sc] == "1_pdx");
  endfunction

  function automatic bit raw_has_unknown_v_bits(input syndram_raw_cmd_sample_t raw);
    return $isunknown(raw.cs_r1) || $isunknown(raw.cs_r2) ||
           !ca_known(raw.ca_r1) || !ca_known(raw.ca_f1) ||
           !ca_known(raw.ca_r2) || !ca_known(raw.ca_f2);
  endfunction

  function automatic bit is_sequence_cmd(input syndram_cmd_event_t ev);
    return ev.valid &&
           ev.cmd_type != CMD_DESELECT &&
           ev.cmd_type != CMD_NOP;
  endfunction

  function automatic bit is_meta_carveout_column(input logic [5:0] column);
    return !$isunknown(column[5:2]) && column[5:2] == 4'b1111;
  endfunction

  function automatic int unsigned fsp_storage_index(input logic [1:0] fsp);
    if (!$isunknown(fsp) && fsp <= 2'd2) begin
      return int'(fsp);
    end
    return 0;
  endfunction

  function automatic logic [7:0] get_mr_value(
      input int unsigned sc,
      input logic [7:0] ma
  );
    logic [7:0] fsp_mask;
    logic [7:0] common_value;
    logic [7:0] fsp_value;
    fsp_mask = syndram_mr_fsp_mask(ma);
    common_value = mr_storage[sc][ma];
    fsp_value = fsp_mr_storage[sc][fsp_storage_index(mr_fsp_op[sc])][ma];
    return (common_value & ~fsp_mask) | (fsp_value & fsp_mask);
  endfunction

  function automatic logic [7:0] get_fsp_mr_value(
      input int unsigned sc,
      input logic [1:0] fsp,
      input logic [7:0] ma
  );
    logic [7:0] fsp_mask;
    logic [7:0] common_value;
    logic [7:0] fsp_value;
    fsp_mask = syndram_mr_fsp_mask(ma);
    common_value = mr_storage[sc][ma];
    fsp_value = fsp_mr_storage[sc][fsp_storage_index(fsp)][ma];
    return (common_value & ~fsp_mask) | (fsp_value & fsp_mask);
  endfunction

  task automatic apply_mrw_storage_write(
      input int unsigned dst_sc,
      input logic [7:0] ma,
      input logic [7:0] op,
      input logic [7:0] policy_write_mask,
      input syndram_cmd_event_t source_event
  );
    logic [7:0] fsp_mask;
    logic [7:0] writable_mask;
    logic [7:0] common_write_mask;
    logic [7:0] fsp_write_mask;
    logic [7:0] common_old;
    logic [7:0] fsp_old;
    logic [7:0] fsp0_old;
    logic [7:0] common_new;
    logic [7:0] fsp_new;
    logic [7:0] fsp0_new;
    logic [7:0] active_fsp_value;
    logic [7:0] refresh_fsp_mask;
    logic [1:0] old_fsp_op;
    int unsigned fsp_idx;
    int unsigned active_fsp_idx;
    int refresh_mr_addr;

    if (dst_sc < NUM_SUBCH) begin
      fsp_mask = syndram_mr_fsp_mask(ma);
      writable_mask = syndram_mr_writable_mask(ma) & policy_write_mask;
      common_write_mask = writable_mask & ~fsp_mask;
      fsp_write_mask = writable_mask & fsp_mask;
      fsp_idx = fsp_storage_index(mr_fsp_wr[dst_sc]);
      active_fsp_idx = fsp_storage_index(mr_fsp_op[dst_sc]);
      old_fsp_op = mr_fsp_op[dst_sc];

      common_old = mr_storage[dst_sc][ma];
      fsp_old = fsp_mr_storage[dst_sc][fsp_idx][ma];
      fsp0_old = fsp_mr_storage[dst_sc][0][ma];

      common_new =
          (common_old & ~common_write_mask) |
          (op & common_write_mask);
      fsp_new =
          (fsp_old & ~fsp_write_mask) |
          (op & fsp_write_mask);
      fsp0_new =
          (fsp0_old & ~common_write_mask) |
          (op & common_write_mask);
      if (fsp_idx == 0) begin
        fsp0_new =
            (fsp0_new & ~fsp_write_mask) |
            (op & fsp_write_mask);
      end

      // Keep FSP0 as the common-bit mirror and update the selected FSP-WR bank.
      fsp_mr_storage[dst_sc][0][ma] = fsp0_new;
      if (fsp_idx != 0) begin
        fsp_mr_storage[dst_sc][fsp_idx][ma] = fsp_new;
      end

      // mr_storage is the complete MR view selected by the current FSP-OP.
      if (active_fsp_idx == 0) begin
        active_fsp_value = fsp0_new;
      end else if (active_fsp_idx == fsp_idx) begin
        active_fsp_value = fsp_new;
      end else begin
        active_fsp_value = fsp_mr_storage[dst_sc][active_fsp_idx][ma];
      end
      mr_storage[dst_sc][ma] =
          (common_new & ~fsp_mask) | (active_fsp_value & fsp_mask);

      if (ma == 8'd13) begin
        // Keep the cached selectors consistent with the masked MR13 value.
        // A policy-rejected MR13 write therefore cannot change the active FSP.
        mr_fsp_wr[dst_sc] = common_new[5:4];
        mr_fsp_op[dst_sc] = common_new[7:6];

        if (mr_fsp_op[dst_sc] != old_fsp_op) begin
          active_fsp_idx = fsp_storage_index(mr_fsp_op[dst_sc]);
          for (refresh_mr_addr = 0; refresh_mr_addr < 256; refresh_mr_addr++) begin
            refresh_fsp_mask = syndram_mr_fsp_mask(refresh_mr_addr[7:0]);
            mr_storage[dst_sc][refresh_mr_addr] =
                (mr_storage[dst_sc][refresh_mr_addr] & ~refresh_fsp_mask) |
                (fsp_mr_storage[dst_sc][active_fsp_idx][refresh_mr_addr] &
                 refresh_fsp_mask);
          end
        end
      end

      // Publish one update per destination subchannel after its effective view is complete.
      mr_storage_change_event[dst_sc] = source_event;
      mr_storage_change_event[dst_sc].sc = dst_sc[0];
      mr_storage_change_event[dst_sc].subch = dst_sc[0];
      -> mr_storage_changed[dst_sc];
    end
  endtask

  function automatic syndram_cmd_event_t decode_syndram_command(
    input int unsigned sc,
    input syndram_raw_cmd_sample_t raw
  );
    syndram_cmd_event_t ev;
    bit normalized_protocol_field_sc;
    ev = syndram_cmd_event_zero();
    ev.valid = 1'b1;
    ev.subch = sc[0];
    ev.sc = sc[0];
    ev.protocol_field_sc = 1'b0;
    ev.target = 1'b1;
    ev.cmd_type = CMD_UNKNOWN;
    ev.bl = BL_UNKNOWN;
    ev.raw = raw;
    ev.ck_sync_state = ck_sync_state[sc];
    ev.efficiency_mode = efficiency_mode_active();
    // CA3-F1 is an SC operand only in Efficiency mode. In Normal mode it is
    // a defined V bit, so the physical command interface identifies the SC.
    normalized_protocol_field_sc = ev.efficiency_mode ? raw.ca_f1[3] : sc[0];
    ev.ca_parity_enabled = ca_parity_enabled[sc];
    ev.system_meta_mode = system_meta_mode[sc];
    ev.timestamp = raw.f2_time;

    // The generated model currently represents one monitored target rank.
    // Do not publish commands observed on another rank.
    if (rank[sc] !== 1'b0) begin
      ev.valid = 1'b0;
      return ev;
    end

    if (sc != 0 && ev.efficiency_mode &&
        ($isunknown(raw.cs_r1) || $isunknown(raw.cs_r2))) begin
      ev.valid = 1'b0;
      return ev;
    end

    if (raw.cs_r1 === 1'b0) begin
      ev.cmd_type = CMD_DESELECT;
      ev.valid = !($isunknown(raw.cs_r1));
      return ev;
    end

    if (bit_is(raw.cs_r1, 1'b1) && bit_is(raw.cs_r2, 1'b0) &&
        bit_is(raw.ca_r1[0], 1'b1) && bit_known(raw.ca_f1[0]) &&
        bit_known(raw.ca_r2[0]) && bit_known(raw.ca_f2[0])) begin
      ev.cmd_type = CMD_NT_S;
      ev.bl = BL_24;
      ev.target = 1'b0;
      ev.non_target = 1'b1;
      return ev;
    end

    if (bit_is(raw.cs_r1, 1'b1) && bit_is(raw.cs_r2, 1'b0) &&
        bit_is(raw.ca_r1[0], 1'b0) && bit_known(raw.ca_f1[0]) &&
        bit_known(raw.ca_r2[0]) && bit_known(raw.ca_f2[0])) begin
      ev.cmd_type = CMD_NT_L;
      ev.bl = BL_48;
      ev.target = 1'b0;
      ev.non_target = 1'b1;
      return ev;
    end

    if (raw_has_unknown_v_bits(raw)) begin
      ev.cmd_type = CMD_ILLEGAL;
      return ev;
    end

    if (raw.cs_r1 != 1'b1 || raw.cs_r2 != 1'b1) begin
      ev.cmd_type = CMD_ILLEGAL;
      return ev;
    end

    ev.par = raw.ca_r1[3];

    if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[2:0] == 3'b000) begin
      ev.cmd_type = CMD_NOP;
    end else if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[2:0] == 3'b010) begin
      ev.cmd_type = CMD_PDE;
    end else if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[2:0] == 3'b100) begin
      ev.cmd_type = CMD_SRE;
      ev.pd = raw.ca_f1[3];
    end else if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[2:0] == 3'b110) begin
      ev.cmd_type = CMD_SRX;
    end else if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[1:0] == 2'b11) begin
      ev.cmd_type = raw.ca_r2[3] ? CMD_PREA : CMD_PRE;
      ev.bl = BL_UNKNOWN;
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.ab = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b000 && raw.ca_f1[0] == 1'b1 &&
                 raw.ca_f1[1] == 1'b0) begin
      ev.cmd_type = CMD_REFRESH;
      ev.rfm = raw.ca_f1[2];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.dbg[0] = raw.ca_r2[0];
      ev.dbg[1] = raw.ca_r2[1];
      ev.ab = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b111 && raw.ca_f1[0] == 1'b1) begin
      ev.cmd_type = CMD_ACT_1;
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.r[15] = raw.ca_f1[1];
      ev.r[16] = raw.ca_f1[2];
      ev.r[11] = raw.ca_r2[0];
      ev.r[12] = raw.ca_r2[1];
      ev.r[13] = raw.ca_r2[2];
      ev.r[14] = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b111 && raw.ca_f1[0] == 1'b0) begin
      ev.cmd_type = CMD_ACT_2;
      ev.r[8] = raw.ca_f1[1];
      ev.r[9] = raw.ca_f1[2];
      ev.r[10] = raw.ca_f1[3];
      ev.r[4] = raw.ca_r2[0];
      ev.r[5] = raw.ca_r2[1];
      ev.r[6] = raw.ca_r2[2];
      ev.r[7] = raw.ca_r2[3];
      ev.r[0] = raw.ca_f2[0];
      ev.r[1] = raw.ca_f2[1];
      ev.r[2] = raw.ca_f2[2];
      ev.r[3] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b101) begin
      ev.cmd_type = CMD_WR_S;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
      ev.c[0] = raw.ca_f1[0];
      ev.c[1] = raw.ca_f1[1];
      ev.ap = raw.ca_f1[2];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.c[2] = raw.ca_r2[0];
      ev.c[3] = raw.ca_r2[1];
      ev.c[4] = raw.ca_r2[2];
      ev.c[5] = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b100) begin
      ev.cmd_type = CMD_WR_L;
      ev.bl = BL_48;
      ev.ws = raw.ca_r1[3];
      ev.c[0] = 1'b0;
      ev.c[1] = raw.ca_f1[1];
      ev.ap = raw.ca_f1[2];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.c[2] = raw.ca_r2[0];
      ev.c[3] = raw.ca_r2[1];
      ev.c[4] = raw.ca_r2[2];
      ev.c[5] = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b011) begin
      ev.cmd_type = CMD_RD_S;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
      ev.c[0] = raw.ca_f1[0];
      ev.c[1] = raw.ca_f1[1];
      ev.ap = raw.ca_f1[2];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.c[2] = raw.ca_r2[0];
      ev.c[3] = raw.ca_r2[1];
      ev.c[4] = raw.ca_r2[2];
      ev.c[5] = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b010) begin
      ev.cmd_type = CMD_RD_L;
      ev.bl = BL_48;
      ev.ws = raw.ca_r1[3];
      ev.c[0] = raw.ca_f1[0];
      ev.c[1] = raw.ca_f1[1];
      ev.ap = raw.ca_f1[2];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.c[2] = raw.ca_r2[0];
      ev.c[3] = raw.ca_r2[1];
      ev.c[4] = raw.ca_r2[2];
      ev.c[5] = raw.ca_r2[3];
      ev.ba[0] = raw.ca_f2[0];
      ev.ba[1] = raw.ca_f2[1];
      ev.bg[0] = raw.ca_f2[2];
      ev.bg[1] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b111) begin
      ev.cmd_type = CMD_CAS;
      ev.ws = raw.ca_r1[3];
      ev.ws_off = raw.ca_f1[3];
      ev.wsoe = (raw.ca_r1[3] === 1'b0) && (raw.ca_f1[3] === 1'b0);
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b110) begin
      ev.cmd_type = CMD_MRR;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
      ev.protocol_field_sc = normalized_protocol_field_sc;
      ev.ma[4] = raw.ca_r2[0];
      ev.ma[5] = raw.ca_r2[1];
      ev.ma[6] = raw.ca_r2[2];
      ev.ma[7] = raw.ca_r2[3];
      ev.ma[0] = raw.ca_f2[0];
      ev.ma[1] = raw.ca_f2[1];
      ev.ma[2] = raw.ca_f2[2];
      ev.ma[3] = raw.ca_f2[3];
      ev.mr_is_fsp = syndram_mr_is_fsp(ev.ma);
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b101) begin
      ev.cmd_type = CMD_MPC;
      ev.op[4] = raw.ca_r2[0];
      ev.op[5] = raw.ca_r2[1];
      ev.op[6] = raw.ca_r2[2];
      ev.op[7] = raw.ca_r2[3];
      ev.op[0] = raw.ca_f2[0];
      ev.op[1] = raw.ca_f2[1];
      ev.op[2] = raw.ca_f2[2];
      ev.op[3] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b100) begin
      ev.cmd_type = CMD_MRW_1;
      // CA3-F1 is BCST only while the device is already in DEFF mode.
      ev.bcst = dynamic_efficiency_mode_active() && bit_is(raw.ca_f1[3], 1'b1);
      ev.ma[4] = raw.ca_r2[0];
      ev.ma[5] = raw.ca_r2[1];
      ev.ma[6] = raw.ca_r2[2];
      ev.ma[7] = raw.ca_r2[3];
      ev.ma[0] = raw.ca_f2[0];
      ev.ma[1] = raw.ca_f2[1];
      ev.ma[2] = raw.ca_f2[2];
      ev.ma[3] = raw.ca_f2[3];
      ev.mr_is_fsp = syndram_mr_is_fsp(ev.ma);
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b011) begin
      ev.cmd_type = CMD_MRW_2;
      ev.op[4] = raw.ca_r2[0];
      ev.op[5] = raw.ca_r2[1];
      ev.op[6] = raw.ca_r2[2];
      ev.op[7] = raw.ca_r2[3];
      ev.op[0] = raw.ca_f2[0];
      ev.op[1] = raw.ca_f2[1];
      ev.op[2] = raw.ca_f2[2];
      ev.op[3] = raw.ca_f2[3];
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b010) begin
      ev.cmd_type = CMD_WFF;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b001) begin
      ev.cmd_type = CMD_RFF;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
    end else if (raw.ca_r1[2:0] == 3'b001 && raw.ca_f1[2:0] == 3'b000) begin
      ev.cmd_type = CMD_RDC;
      ev.bl = BL_24;
      ev.ws = raw.ca_r1[3];
    end else if (raw.ca_r1[2:0] == 3'b110) begin
      ev.cmd_type = CMD_RFU;
    end else begin
      ev.cmd_type = CMD_ILLEGAL;
    end

    if (ev.cmd_type inside {CMD_WR_S, CMD_RD_S, CMD_WR_L, CMD_RD_L} &&
        is_meta_carveout_column(ev.c) && bit_is(pamm_r1_q[sc], 1'b1)) begin
      ev.meta = 1'b1;
      if (ev.cmd_type == CMD_WR_S) begin
        ev.cmd_type = CMD_WR_M;
      end else if (ev.cmd_type == CMD_RD_S) begin
        ev.cmd_type = CMD_RD_M;
      end else begin
        ev.cmd_type = CMD_ILLEGAL;
      end
    end

    return ev;
  endfunction

  genvar sc_g;
  // Generated config/state sampling reset values.
  always @(negedge RESET_n) begin
    if (!RESET_n) begin

      // Generated config sampling reset values.
      dramconfig_mr0_op2_efficiency_capability <= 1'b0;
      dramconfig_ck_frequency_mhz <= '0;
      dramconfig_wck_frequency <= '0;
      dramconfig_data_rate_mbps <= '0;
      dramconfig_wck_frequency_mhz <= '0;

      // Generated state sampling reset values.
      for (state_sc_i = 0; state_sc_i < 2; state_sc_i++) begin
          for (state_bank_i = 0; state_bank_i < 16; state_bank_i++) begin
          state_phase1_bank_table300_precharge_per_bank[state_sc_i][state_bank_i] <= ypu_syndram_state_zero();
        end
      end
      for (state_sc_i = 0; state_sc_i < 2; state_sc_i++) begin
          for (state_bank_i = 0; state_bank_i < 16; state_bank_i++) begin
          state_phase1_bank_table383_active[state_sc_i][state_bank_i] <= ypu_syndram_state_zero();
        end
      end
      for (state_sc_i = 0; state_sc_i < 2; state_sc_i++) begin
          for (state_bank_i = 0; state_bank_i < 16; state_bank_i++) begin
          state_phase1_bank_table383_precharge[state_sc_i][state_bank_i] <= ypu_syndram_state_zero();
        end
      end
      for (state_sc_i = 0; state_sc_i < 2; state_sc_i++) begin
          for (state_bank_i = 0; state_bank_i < 16; state_bank_i++) begin
          state_phase1_bank_table383_read_bl24_or_bl48[state_sc_i][state_bank_i] <= ypu_syndram_state_zero();
