            cs_r2_q[sc_g] <= CS[sc_g];
            ca_r2_q[sc_g] <= CA[sc_g];
            r2_time_q[sc_g] <= $realtime;
          end

          if (ck_last_posedge_time[sc_g] != 0.0) begin
            // Quantize the measured period to the nearest integer picosecond.
            measured_ck_period = longint'($rtoi(
                (($realtime - ck_last_posedge_time[sc_g]) * 1000.0) + 0.5));
            rate_bin = map_ck_period_to_rate(measured_ck_period);
            ck_period[sc_g] <= measured_ck_period / 1000.0;
            ck_frequency[sc_g] <= rate_bin.ck_frequency_mhz;
            wck_frequency[sc_g] <= rate_bin.wck_frequency_mhz;
            data_rate[sc_g] <= rate_bin.data_rate_mbps;
            ck_frequency_valid[sc_g] <= rate_bin.valid;
            wck_frequency_valid[sc_g] <= rate_bin.valid;
            data_rate_valid[sc_g] <= rate_bin.valid;
          end
          ck_last_posedge_time[sc_g] <= $realtime;

        end
      end

      always @(negedge RESET_n or negedge CK_t[sc_g]) begin
        syndram_raw_cmd_sample_t raw;
        syndram_cmd_event_t decoded;
        logic [7:0] mr_fsp_mask;
        logic [7:0] mr_common_old;
        logic [7:0] mr_fsp_old;
        logic [7:0] mr_current_old;
        logic [7:0] mr_changed_mask;
        logic [7:0] mr_allowed_mask;
        logic [7:0] mr_broadcast_mask;
        logic [7:0] mr_policy_mask;
        int unsigned mr_fsp_idx;
        int mr_init_fsp;
        int mr_init_addr;
        int mr_bcst_sc;
        int seq_i;

        if (!RESET_n) begin
          ca_f1_q[sc_g] <= '0;
          ca_f2_q[sc_g] <= '0;
          pamm_r1_q[sc_g] <= 1'b0;
          f1_time_q[sc_g] <= 0.0;
          f2_time_q[sc_g] <= 0.0;
          last_cmd_event[sc_g] <= syndram_cmd_event_zero();
          act_1_event_q[sc_g] <= syndram_cmd_event_zero();
          mrw_1_event_q[sc_g] <= syndram_cmd_event_zero();
          last_cmd_pair[sc_g] = ypu_syndram_cmd_pair_zero();
          last_cmd_tuple3[sc_g] = ypu_syndram_cmd_tuple3_zero();
          for (seq_i = 0; seq_i < 3; seq_i++) begin
            sequence_cmd_window[sc_g][seq_i] = syndram_cmd_event_zero();
            sequence_cmd_window_valid[sc_g][seq_i] = 1'b0;
          end
          act_1_event_valid[sc_g] <= 1'b0;
          mrw_1_event_valid[sc_g] <= 1'b0;
          power_down_active[sc_g] <= 1'b0;
          refresh_bank_count[sc_g] <= 3'd0;
          refresh_counter_epoch[sc_g] <= 1'b0;
          ck_sync_state[sc_g] <= 1'b0;
          efficiency_mode[sc_g] <= 1'b0;
          deff_entry_mr_coherent[sc_g] <= 1'b0;
          ca_parity_enabled[sc_g] <= 1'b0;
          system_meta_mode[sc_g] <= 1'b0;
          mr_fsp_wr[sc_g] <= 2'b00;
          mr_fsp_op[sc_g] <= 2'b00;
          last_mr_write_old_value[sc_g] <= '0;
          last_mr_write_old_value_valid[sc_g] <= 1'b0;
          mr_storage_change_event[sc_g] <= syndram_cmd_event_zero();
          for (mr_init_addr = 0; mr_init_addr < 256; mr_init_addr++) begin
            mr_storage[sc_g][mr_init_addr] <= syndram_mr_default_value(mr_init_addr[7:0]);
            for (mr_init_fsp = 0; mr_init_fsp < 3; mr_init_fsp++) begin
              fsp_mr_storage[sc_g][mr_init_fsp][mr_init_addr] <=
                  syndram_mr_default_value(mr_init_addr[7:0]);
            end
          end
        end else begin
          efficiency_mode[sc_g] <= efficiency_mode_active();
          if (command_started_q[sc_g]) begin
            check_even_q[sc_g] <= (check_even[sc_g] === 1'b1);
            ca_f2_q[sc_g] <= CA[sc_g];
            f2_time_q[sc_g] <= $realtime;

            raw = make_raw_sample(sc_g);
            raw.ca_f2 = CA[sc_g];
            raw.f2_time = $realtime;
            decoded = decode_syndram_command(sc_g, raw);
            last_mr_write_old_value_valid[sc_g] = 1'b0;

            if (decoded.valid && decoded.cmd_type == CMD_ACT_2) begin
              if (act_1_event_valid[sc_g]) begin
                decoded.ba = act_1_event_q[sc_g].ba;
                decoded.bg = act_1_event_q[sc_g].bg;
                decoded.protocol_field_sc = act_1_event_q[sc_g].protocol_field_sc;
                decoded.r[11] = act_1_event_q[sc_g].r[11];
                decoded.r[12] = act_1_event_q[sc_g].r[12];
                decoded.r[13] = act_1_event_q[sc_g].r[13];
                decoded.r[14] = act_1_event_q[sc_g].r[14];
                decoded.r[15] = act_1_event_q[sc_g].r[15];
                decoded.r[16] = act_1_event_q[sc_g].r[16];
              end else begin
                decoded.valid = 1'b0;
              end
            end

            if (decoded.valid && decoded.cmd_type == CMD_MRW_2) begin
              if (mrw_1_event_valid[sc_g]) begin
                decoded.ma = mrw_1_event_q[sc_g].ma;
                decoded.bcst = mrw_1_event_q[sc_g].bcst;
                decoded.mr_is_fsp = mrw_1_event_q[sc_g].mr_is_fsp;
              end else begin
                decoded.valid = 1'b0;
              end
            end

            if (is_dft[sc_g] && decoded.cmd_type != CMD_MRW_1 && decoded.cmd_type != CMD_MRW_2) begin
              decoded.valid = 1'b0;
              act_1_event_valid[sc_g] <= 1'b0;
              mrw_1_event_valid[sc_g] <= 1'b0;
              power_down_active[sc_g] <= 1'b0;
            end else if (decoded.valid) begin
              if (decoded.cmd_type == CMD_REFRESH && !decoded.rfm && !decoded.ab) begin
                decoded.refresh_counter = refresh_counter_epoch[sc_g];
                decoded.refresh_counter_valid = 1'b1;
                if (refresh_bank_count[sc_g] == 3'd7) begin
                  refresh_bank_count[sc_g] <= 3'd0;
                  refresh_counter_epoch[sc_g] <= ~refresh_counter_epoch[sc_g];
                end else begin
                  refresh_bank_count[sc_g] <= refresh_bank_count[sc_g] + 3'd1;
                end
              end else if ((decoded.cmd_type == CMD_REFRESH && !decoded.rfm && decoded.ab) ||
                           decoded.cmd_type == CMD_SRX) begin
                refresh_bank_count[sc_g] <= 3'd0;
                refresh_counter_epoch[sc_g] <= ~refresh_counter_epoch[sc_g];
              end
              if (decoded.cmd_type == CMD_ACT_1) begin
                act_1_event_q[sc_g] <= decoded;
                act_1_event_valid[sc_g] <= 1'b1;
              end else if (decoded.cmd_type == CMD_ACT_2) begin
                act_1_event_valid[sc_g] <= 1'b0;
              end

              if (decoded.cmd_type == CMD_MRW_1) begin
                mrw_1_event_q[sc_g] <= decoded;
                mrw_1_event_valid[sc_g] <= 1'b1;
              end else if (decoded.cmd_type == CMD_MRW_2) begin
                mrw_1_event_valid[sc_g] <= 1'b0;
                // Compare active register views before
                // this write; MR1 control and MR11 WCKFM are not equality bits.
                deff_entry_mr_coherent[sc_g] =
                    (((get_mr_value(0,1) ^ get_mr_value(1,1)) & 8'hbf) == 0) &&
                    (((get_mr_value(0,11) ^ get_mr_value(1,11)) & 8'h3c) == 0) &&
                    (((get_mr_value(0,13) ^ get_mr_value(1,13)) & 8'hf0) == 0) &&
                    (((get_mr_value(0,25) ^ get_mr_value(1,25)) & 8'h80) == 0);
                last_mr_write_old_value_valid[sc_g] = 1'b1;
                mr_fsp_mask = syndram_mr_fsp_mask(decoded.ma);
                mr_fsp_idx = fsp_storage_index(mr_fsp_wr[sc_g]);
                mr_common_old = mr_storage[sc_g][decoded.ma];
                mr_fsp_old = fsp_mr_storage[sc_g][mr_fsp_idx][decoded.ma];
                mr_current_old =
                    (mr_common_old & ~mr_fsp_mask) | (mr_fsp_old & mr_fsp_mask);
                last_mr_write_old_value[sc_g] = mr_current_old;

                if (static_efficiency_mode_active()) begin
                  if (sc_g != 0) begin
                    $warning("SYNDRAM SEFF MRW observed on secondary subchannel %0d", sc_g);
                  end else begin
                    for (mr_bcst_sc = 0; mr_bcst_sc < NUM_SUBCH; mr_bcst_sc++) begin
                      apply_mrw_storage_write(
                          mr_bcst_sc, decoded.ma, decoded.op, 8'hff, decoded);
                    end
                  end
                end else if (dynamic_efficiency_mode_active()) begin
                  mr_allowed_mask = syndram_mr_deff_allowed_mask(decoded.ma);
                  mr_broadcast_mask = syndram_mr_deff_broadcast_mask(decoded.ma);
                  mr_changed_mask =
                      (decoded.op ^ mr_current_old) & syndram_mr_writable_mask(decoded.ma);

                  if (sc_g != 0) begin
                    $warning("SYNDRAM DEFF MRW observed on secondary subchannel %0d", sc_g);
                  end else begin
                    if ((mr_changed_mask & ~mr_allowed_mask) != 8'h00) begin
                      $warning("SYNDRAM DEFF MRW attempted disallowed change: MR%0d mask=%02h",
                               decoded.ma, mr_changed_mask & ~mr_allowed_mask);
                    end
                    if (!decoded.bcst &&
                        ((mr_changed_mask & mr_broadcast_mask) != 8'h00)) begin
                      $warning("SYNDRAM DEFF MRW requires BCST=1: MR%0d mask=%02h",
                               decoded.ma, mr_changed_mask & mr_broadcast_mask);
                    end

                    if (decoded.bcst) begin
                      for (mr_bcst_sc = 0; mr_bcst_sc < NUM_SUBCH; mr_bcst_sc++) begin
                        mr_policy_mask = mr_allowed_mask;
                        // MR1 OP[6] controls DEFF only at the primary subchannel.
                        if (decoded.ma == 8'd1 && mr_bcst_sc != 0) begin
                          mr_policy_mask = mr_policy_mask & 8'hbf;
                        end
                        apply_mrw_storage_write(
                            mr_bcst_sc, decoded.ma, decoded.op, mr_policy_mask, decoded);
                      end
                    end else begin
                      mr_policy_mask = mr_allowed_mask & ~mr_broadcast_mask;
                      apply_mrw_storage_write(
                          sc_g, decoded.ma, decoded.op, mr_policy_mask, decoded);
                    end
                  end
                end else if (normal_mode_active()) begin
                  apply_mrw_storage_write(sc_g, decoded.ma, decoded.op, 8'hff, decoded);
                end else begin
                  $warning("SYNDRAM MRW mode inputs contain X/Z; applying normal per-subchannel semantics");
                  apply_mrw_storage_write(sc_g, decoded.ma, decoded.op, 8'hff, decoded);
                end
              end

              if (decoded.cmd_type == CMD_PDE ||
                  (decoded.cmd_type == CMD_SRE && decoded.pd)) begin
                power_down_active[sc_g] <= 1'b1;
              end else if (decoded.cmd_type == CMD_PDX) begin
                power_down_active[sc_g] <= 1'b0;
              end

              if (is_sequence_cmd(decoded)) begin
                if (sequence_cmd_window_valid[sc_g][2]) begin
                  last_cmd_pair[sc_g].valid = 1'b1;
                  last_cmd_pair[sc_g].previous = sequence_cmd_window[sc_g][2];
                  last_cmd_pair[sc_g].current = decoded;
                  last_cmd_pair[sc_g].previous_time = sequence_cmd_window[sc_g][2].timestamp;
                  last_cmd_pair[sc_g].current_time = decoded.timestamp;
                  -> subch_cmd_pair_sampled[sc_g];
                  -> cmd_pair_sampled;
                end else begin
                  last_cmd_pair[sc_g].valid = 1'b0;
                end

                if (sequence_cmd_window_valid[sc_g][1] &&
                    sequence_cmd_window_valid[sc_g][2]) begin
                  last_cmd_tuple3[sc_g].valid = 1'b1;
                  last_cmd_tuple3[sc_g].ev0 = sequence_cmd_window[sc_g][1];
                  last_cmd_tuple3[sc_g].ev1 = sequence_cmd_window[sc_g][2];
                  last_cmd_tuple3[sc_g].ev2 = decoded;
                  last_cmd_tuple3[sc_g].time0 = sequence_cmd_window[sc_g][1].timestamp;
                  last_cmd_tuple3[sc_g].time1 = sequence_cmd_window[sc_g][2].timestamp;
                  last_cmd_tuple3[sc_g].time2 = decoded.timestamp;
                  -> subch_cmd_tuple3_sampled[sc_g];
                  -> cmd_tuple3_sampled;
                end else begin
                  last_cmd_tuple3[sc_g].valid = 1'b0;
                end

                sequence_cmd_window[sc_g][0] = sequence_cmd_window[sc_g][1];
                sequence_cmd_window[sc_g][1] = sequence_cmd_window[sc_g][2];
                sequence_cmd_window[sc_g][2] = decoded;
                sequence_cmd_window_valid[sc_g][0] = sequence_cmd_window_valid[sc_g][1];
                sequence_cmd_window_valid[sc_g][1] = sequence_cmd_window_valid[sc_g][2];
                sequence_cmd_window_valid[sc_g][2] = 1'b1;
              end else begin
                last_cmd_pair[sc_g].valid = 1'b0;
                last_cmd_tuple3[sc_g].valid = 1'b0;
              end
            end

            last_cmd_event[sc_g] <= decoded;
            command_started_q[sc_g] <= 1'b0;
            if (decoded.valid) begin
              -> subch_command_sampled[sc_g];
              sampled_cmd_event[sc_g] = decoded;
              -> command_sampled[sc_g];
            end
          end else if (check_even[sc_g] === 1'b1 && !check_even_q[sc_g]) begin
            check_even_q[sc_g] <= 1'b1;
            cs_r1_q[sc_g] <= cs_pos_q[sc_g];
            ca_r1_q[sc_g] <= ca_pos_q[sc_g];
            pamm_r1_q[sc_g] <= pamm_pos_q[sc_g];
            r1_time_q[sc_g] <= pos_time_q[sc_g];
            ca_f1_q[sc_g] <= CA[sc_g];
            f1_time_q[sc_g] <= $realtime;
            command_started_q[sc_g] <= 1'b1;
          end else begin
            check_even_q[sc_g] <= (check_even[sc_g] === 1'b1);
          end
        end
      end


    always @(posedge mrr_valid[sc_g]) begin
      if (RESET_n) begin
        -> subch_mrr_sampled[sc_g];
        -> mrr_sampled;
      end
    end
  end
  endgenerate

  // Generated config/state/timing sampling from decoded SYNDRAM command events.
  generate
    for (genvar sampled_sc_g = 0; sampled_sc_g < NUM_SUBCH; sampled_sc_g++) begin : gen_generated_command_sampling
      always @(command_sampled[sampled_sc_g]) begin
        int state_sc_i;
        int state_bg_i;
        int state_bank_i;
        int state_latest_bank_i;
        int state_latest_bank;
        logic state_latest_bank_found;
        int state_latest_bg_i;
        int state_latest_bg;
        logic state_latest_bg_found;

      // Clear timing samples and timing history while DFT/CBT command sampling is suppressed.
      if (is_dft[sampled_sc_g] || is_cbt[sampled_sc_g]) begin
        rule_interval_table383_active_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_active_to_write[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_active_to_precharge[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table386_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table386_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table386_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_read_bl24_or_bl48_to_precharge[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table386_read_bl24_or_bl48_to_precharge[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_write_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_write_bl24_or_bl48_to_write[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_write_bl24_or_bl48_to_precharge[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table383_precharge_to_active[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_active_to_active[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table387_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table387_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table387_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_write_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table384_write_bl24_or_bl48_to_write[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_active_to_active[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table388_read_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table388_read_bl24_or_bl48_to_write_nt_off[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table388_read_bl24_or_bl48_to_write_nt_on[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_write_bl24_or_bl48_to_read[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table385_write_bl24_or_bl48_to_write[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table391_read_with_ap_bl24_or_bl48_to_active[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table391_read_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table391_write_with_ap_bl24_or_bl48_to_active[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table391_write_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_read_with_ap_bl24_or_bl48_to_read_or_read_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_read_with_ap_bl24_or_bl48_to_write_or_write_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_read_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_write_with_ap_bl24_or_bl48_to_read_or_read_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_write_with_ap_bl24_or_bl48_to_write_or_write_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table392_write_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_read_with_ap_bl24_or_bl48_to_read_or_read_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_read_with_ap_bl24_or_bl48_to_write_or_write_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_read_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_write_with_ap_bl24_or_bl48_to_read_or_read_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_write_with_ap_bl24_or_bl48_to_write_or_write_with_ap[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table393_write_with_ap_bl24_or_bl48_to_precharge_all[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table394_cas_ws_1_ws_off_0_to_cas_ws_0_ws_off_1[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table399_mrr_to_mrr[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table399_mrr_to_mrw_unaffected[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
        rule_interval_table399_mrr_to_mrw_unaffected_start[sampled_sc_g] = ypu_syndram_timing_start_zero();
        rule_interval_table399_rd_to_mrr[sampled_sc_g] = ypu_syndram_timing_interval_sample_zero();
