  // Generated state sampling from DQ values captured on WCK rising edges.
  generate
    for (genvar pin_sample_sc_g = 0; pin_sample_sc_g < NUM_SUBCH; pin_sample_sc_g++) begin : gen_generated_pin_sampling
      always @(posedge WCK_t[pin_sample_sc_g]) begin
        sampled_pin_event[pin_sample_sc_g] = syndram_cmd_event_zero();
        sampled_pin_event[pin_sample_sc_g].valid = 1'b1;
        sampled_pin_event[pin_sample_sc_g].sc = pin_sample_sc_g[0];
        sampled_pin_event[pin_sample_sc_g].subch = pin_sample_sc_g[0];
        sampled_pin_event[pin_sample_sc_g].timestamp = $realtime;

        // Generated state sampling from sample_pin events.
        if ((!$isunknown(DQ[pin_sample_sc_g][11]) && DQ[pin_sample_sc_g][11] == 1'b1 && state_state_cbt_mode_selected[pin_sample_sc_g].active)) begin
          state_state_cbt_mode_active[pin_sample_sc_g].active = 1'b1;
          state_state_cbt_mode_active[pin_sample_sc_g].enter_time = $realtime;
          state_state_cbt_mode_active[pin_sample_sc_g].enter_event = sampled_pin_event[pin_sample_sc_g];
        end
        if (!$isunknown(DQ[pin_sample_sc_g][11]) && DQ[pin_sample_sc_g][11] == 1'b0) begin
          state_state_cbt_mode_active[pin_sample_sc_g].active = 1'b0;
          state_state_cbt_mode_active[pin_sample_sc_g].exit_time = $realtime;
          state_state_cbt_mode_active[pin_sample_sc_g].exit_event = sampled_pin_event[pin_sample_sc_g];
        end
      end
    end
  endgenerate

  // Generated state sampling from SYNDRAM MRR return data events.
  generate
    for (genvar sampled_mrr_sc_g = 0; sampled_mrr_sc_g < NUM_SUBCH; sampled_mrr_sc_g++) begin : gen_generated_mrr_sampling
      always @(subch_mrr_sampled[sampled_mrr_sc_g]) begin
        if (mrr_valid[sampled_mrr_sc_g]) begin
          sampled_mrr_event[sampled_mrr_sc_g] = syndram_cmd_event_zero();
          sampled_mrr_event[sampled_mrr_sc_g].valid = 1'b1;
          sampled_mrr_event[sampled_mrr_sc_g].cmd_type = CMD_MRR;
          sampled_mrr_event[sampled_mrr_sc_g].sc = sampled_mrr_sc_g[0];
          sampled_mrr_event[sampled_mrr_sc_g].subch = sampled_mrr_sc_g[0];
          sampled_mrr_event[sampled_mrr_sc_g].ma = mrr_ma[sampled_mrr_sc_g];
          sampled_mrr_event[sampled_mrr_sc_g].op = mrr_op[sampled_mrr_sc_g];
          sampled_mrr_event[sampled_mrr_sc_g].timestamp = $realtime;

        // Generated state sampling from read_mr return data.
        if ((state_state_fsp_switch_in_progress[sampled_mrr_sc_g].active && state_state_fsp_switch_in_progress[sampled_mrr_sc_g].enter_time == $realtime)) begin
          state_state_ck_non_sync_before_sync_nop[sampled_mrr_sc_g].active = 1'b1;
          state_state_ck_non_sync_before_sync_nop[sampled_mrr_sc_g].enter_time = $realtime;
          state_state_ck_non_sync_before_sync_nop[sampled_mrr_sc_g].enter_event = sampled_mrr_event[sampled_mrr_sc_g];
        end
        if ((state_state_cbt_mode_active[sampled_mrr_sc_g].active && state_state_cbt_mode_active[sampled_mrr_sc_g].enter_time == $realtime)) begin
