          state_state_ck_non_sync_before_sync_nop[sampled_mrr_sc_g].enter_time = $realtime;
          state_state_ck_non_sync_before_sync_nop[sampled_mrr_sc_g].enter_event = sampled_mrr_event[sampled_mrr_sc_g];
        end
        end
      end
    end
  endgenerate

  function automatic realtime ru_to_nck(input realtime ratio, input realtime nck_value);
    realtime eps;
    begin
      eps = 1.0e-9;
      if (ratio <= eps) begin
        ru_to_nck = 0.0;
      end else begin
        ru_to_nck = $ceil(ratio - eps) * nck_value;
      end
    end
  endfunction

  function automatic realtime round_up_even(input realtime value);
    realtime eps;
    realtime nearest_integer;
    realtime normalized_value;
    begin
      eps = 1.0e-9;
      nearest_integer = $floor(value + 0.5);
      if ((value - nearest_integer <= eps) &&
          (nearest_integer - value <= eps)) begin
        normalized_value = nearest_integer;
      end else begin
        normalized_value = value;
      end
      round_up_even = 2.0 * $ceil(normalized_value / 2.0);
    end
  endfunction

  // Generated timing parameter calculations.
  always_comb begin
    for (int timing_sc_i = 0; timing_sc_i < NUM_SUBCH; timing_sc_i++) begin
      nCK[timing_sc_i] = ck_period[timing_sc_i];
      nCK_valid[timing_sc_i] = ck_frequency_valid[timing_sc_i] && ck_period[timing_sc_i] > 0.0;
      WL[timing_sc_i] = 0.0;
      WL_valid[timing_sc_i] = 1'b0;
      ODTLon[timing_sc_i] = 0.0;
      ODTLon_valid[timing_sc_i] = 1'b0;
      RL[timing_sc_i] = 0.0;
      RL_valid[timing_sc_i] = 1'b0;
      nACU[timing_sc_i] = 0.0;
      nACU_valid[timing_sc_i] = 1'b0;
      nWTP[timing_sc_i] = 0.0;
      nWTP_valid[timing_sc_i] = 1'b0;
      tACU[timing_sc_i] = 0.0;
      tACU_valid[timing_sc_i] = 1'b0;
